def permute_unique(nums):
    res = []

    def dfs(i):
        if i == len(nums):
            res.append(nums[:])
            return
        tried = set()                  # values already placed in slot i
        for j in range(i, len(nums)):
            if nums[j] in tried:
                continue
            tried.add(nums[j])
            nums[i], nums[j] = nums[j], nums[i]
            dfs(i + 1)
            nums[i], nums[j] = nums[j], nums[i]

    dfs(0)
    return res
